import{_ as o,a0 as r,w as m,s,ao as n,I as a,a1 as i,A as p,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 5 - Setup RAID Level 6 (Striping with Double Distributed Parity) in Linux","title":"在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗）","tag":"RAID","desc":""},"relativePath":"RAID/Part 5 - Setup RAID Level 6 (Striping with Double Distributed Parity) in Linux.md","filePath":"[post].md"}'),c={name:"RAID/Part 5 - Setup RAID Level 6 (Striping with Double Distributed Parity) in Linux.md"};function l(R,e,D,u,w,A){const d=r("Link");return m(),s("div",null,[e[17]||(e[17]=n('<h1 id="在-linux-下使用-raid-五-安裝-raid-6-條帶化雙分佈式奇偶校驗" tabindex="-1">在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗） <a class="header-anchor" href="#在-linux-下使用-raid-五-安裝-raid-6-條帶化雙分佈式奇偶校驗" aria-label="Permalink to “在 Linux 下使用 RAID（五）：安裝 RAID 6（條帶化雙分佈式奇偶校驗）”">​</a></h1><p>RAID 6 是 RAID 5 的升級版，它有兩個分佈式奇偶校驗，即使兩個磁盤發生故障後依然有容錯能力。在兩個磁盤同時發生故障時，系統的關鍵任務仍然能運行。它與 RAID 5 相似，但性能更健壯，因為它多用了一個磁盤來進行奇偶校驗。</p><p>在之前的文章中，我們已經在 RAID 5 看了分佈式奇偶校驗，但在本文中，我們將看到的是 RAID 6 雙分佈式奇偶校驗。不要期望比其他 RAID 有更好的性能，除非你也安裝了一個專用的 RAID 控制器。在 RAID 6 中，即使我們失去了2個磁盤，我們仍可以通過更換磁盤，從校驗中構建數據，然後取回數據。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Setup-RAID-6-in-Linux.jpg" alt="Setup RAID 6 in CentOS"></p><p><em>在 Linux 中安裝 RAID 6</em></p><p>要建立一個 RAID 6，一組最少需要4個磁盤。RAID 6 甚至在有些組中會有更多磁盤，這樣將多個硬盤捆在一起，當讀取數據時，它會同時從所有磁盤讀取，所以讀取速度會更快，當寫數據時，因為它要將數據寫在條帶化的多個磁盤上，所以性能會較差。</p><p>現在，很多人都在討論為什麼我們需要使用 RAID 6，它的性能和其他 RAID 相比並不太好。提出這個問題首先需要知道的是，如果需要高容錯性就選擇 RAID 6。在每一個用於資料庫的高可用性要求較高的環境中，他們需要 RAID 6 因為資料庫是最重要，無論花費多少都需要保護其安全，它在視頻流環境中也是非常有用的。</p><h4 id="raid-6-的的優點和缺點" tabindex="-1">RAID 6 的的優點和缺點 <a class="header-anchor" href="#raid-6-的的優點和缺點" aria-label="Permalink to “RAID 6 的的優點和缺點”">​</a></h4><ul><li>性能不錯。</li><li>RAID 6 比較昂貴，因為它要求兩個獨立的磁盤用於奇偶校驗功能。</li><li>將失去兩個磁盤的容量來保存奇偶校驗信息（雙奇偶校驗）。</li><li>即使兩個磁盤損壞，數據也不會丟失。我們可以在更換損壞的磁盤後從校驗中重建數據。</li><li>讀性能比 RAID 5 更好，因為它從多個磁盤讀取，但對於沒有專用的 RAID 控制器的設備寫性能將非常差。</li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>要創建一個 RAID 6 最少需要4個磁盤。你也可以添加更多的磁盤，但你必須有專用的 RAID 控制器。使用軟件 RAID 我們在 RAID 6 中不會得到更好的性能，所以我們需要一個物理 RAID 控制器。</p><p>如果你新接觸 RAID 設置，我們建議先看完以下 RAID 文章。</p>',12)),a("ul",null,[a("li",null,[i(d,{href:"https://linux.cn/article-6085-1.html"},{default:p(()=>[...e[0]||(e[0]=[t("介紹 RAID 的級別和概念",-1)])]),_:1})]),a("li",null,[i(d,{href:"https://linux.cn/article-6087-1.html"},{default:p(()=>[...e[1]||(e[1]=[t("使用 mdadm 工具創建軟件 RAID 0 （條帶化）",-1)])]),_:1})]),a("li",null,[i(d,{href:"https://linux.cn/article-6093-1.html"},{default:p(()=>[...e[2]||(e[2]=[t("用兩塊磁盤創建 RAID 1（鏡像）",-1)])]),_:1})]),a("li",null,[i(d,{href:"4"},{default:p(()=>[...e[3]||(e[3]=[t("創建 RAID 5（條帶化與分佈式奇偶校驗）",-1)])]),_:1})])]),e[18]||(e[18]=n(`<h4 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h4><pre><code>操作系統 :	CentOS 6.5 Final
IP 地址	 :	192.168.0.228
主機名	 :	rd6.tecmintlocal.com
磁盤 1 [20GB]	 :	/dev/sdb
磁盤 2 [20GB]	 :	/dev/sdc
磁盤 3 [20GB]	 :	/dev/sdd
磁盤 4 [20GB]	 : 	/dev/sde
</code></pre><p>這是9篇系列教程的第5部分，在這裏我們將看到如何在 Linux 系統或者服務器上使用四個 20GB 的磁盤（名為 /dev/sdb、 /dev/sdc、 /dev/sdd 和 /dev/sde）創建和設置軟件 RAID 6 （條帶化雙分佈式奇偶校驗）。</p><h3 id="第1步-安裝-mdadm-工具-並檢查磁盤" tabindex="-1">第1步：安裝 mdadm 工具，並檢查磁盤 <a class="header-anchor" href="#第1步-安裝-mdadm-工具-並檢查磁盤" aria-label="Permalink to “第1步：安裝 mdadm 工具，並檢查磁盤”">​</a></h3><p>1、 如果你按照我們最進的兩篇 RAID 文章（第2篇和第3篇），我們已經展示瞭如何安裝<code>mdadm</code>工具。如果你直接看的這篇文章，我們先來解釋下在 Linux 系統中如何使用<code>mdadm</code>工具來創建和管理 RAID，首先根據你的 Linux 發行版使用以下命令來安裝。</p><pre><code># yum install mdadm		[在 RedHat 系統]
# apt-get install mdadm 	[在 Debain 系統]
</code></pre><p>2、 安裝該工具後，然後來驗證所需的四個磁盤，我們將會使用下面的<code>fdisk</code>命令來檢查用於創建 RAID 的磁盤。</p><pre><code># fdisk -l | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Linux-Disks.png" alt="Check Hard Disk in Linux"></p><p><em>在 Linux 中檢查磁盤</em></p><p>3、 在創建 RAID 磁盤前，先檢查下我們的磁盤是否創建過 RAID 分區。</p><pre><code># mdadm -E /dev/sd[b-e]
# mdadm --examine /dev/sdb /dev/sdc /dev/sdd /dev/sde # 或
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Disk-Raid.png" alt="Check Raid on Disk"></p><p><em>在磁盤上檢查 RAID 分區</em></p><p><strong>注意</strong>: 在上面的圖片中，沒有檢測到任何 super-block 或者説在四個磁盤上沒有 RAID 存在。現在我們開始創建 RAID 6。</p><h3 id="第2步-為-raid-6-創建磁盤分區" tabindex="-1">第2步：為 RAID 6 創建磁盤分區 <a class="header-anchor" href="#第2步-為-raid-6-創建磁盤分區" aria-label="Permalink to “第2步：為 RAID 6 創建磁盤分區”">​</a></h3><p>4、 現在在 <code>/dev/sdb</code>, <code>/dev/sdc</code>, <code>/dev/sdd</code> 和 <code>/dev/sde</code>上為 RAID 創建分區，使用下面的 fdisk 命令。在這裏，我們將展示如何在 sdb 磁盤創建分區，同樣的步驟也適用於其他分區。</p><p><strong>創建 /dev/sdb 分區</strong></p><pre><code># fdisk /dev/sdb
</code></pre><p>請按照説明進行操作，如下圖所示創建分區。</p><ul><li>按 <code>n</code>創建新的分區。</li><li>然後按 <code>P</code> 選擇主分區。</li><li>接下來選擇分區號為1。</li><li>只需按兩次回車鍵選擇默認值即可。</li><li>然後，按 <code>P</code> 來打印創建好的分區。</li><li>按 <code>L</code>，列出所有可用的類型。</li><li>按 <code>t</code> 去修改分區。</li><li>鍵入 <code>fd</code> 設置為 Linux 的 RAID 類型，然後按回車確認。</li><li>然後再次使用<code>p</code>查看我們所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sdb-Partition.png" alt="Create sdb Partition"></p><p><em>創建 /dev/sdb 分區</em></p><p><strong>創建 /dev/sdc 分區</strong></p><pre><code># fdisk /dev/sdc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sdc-Partition.png" alt="Create sdc Partition"></p><p><em>創建 /dev/sdc 分區</em></p><p><strong>創建 /dev/sdd 分區</strong></p><pre><code># fdisk /dev/sdd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sdd-Partition.png" alt="Create sdd Partition"></p><p><em>創建 /dev/sdd 分區</em></p><p><strong>創建 /dev/sde 分區</strong></p><pre><code># fdisk /dev/sde
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sde-Partition.png" alt="Create sde Partition"></p><p><em>創建 /dev/sde 分區</em></p><p>5、 創建好分區後，檢查磁盤的 super-blocks 是個好的習慣。如果 super-blocks 不存在我們可以按前面的創建一個新的 RAID。</p><pre><code># mdadm -E /dev/sd[b-e]1    
# mdadm --examine /dev/sdb1 /dev/sdc1 /dev/sdd1 /dev/sde1 # 或
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-on-New-Partitions.png" alt="Check Raid on New Partitions"></p><p>*在新分區中檢查 RAID *</p><h3 id="步驟3-創建-md-設備-raid" tabindex="-1">步驟3：創建 md 設備（RAID） <a class="header-anchor" href="#步驟3-創建-md-設備-raid" aria-label="Permalink to “步驟3：創建 md 設備（RAID）”">​</a></h3><p>6、 現在可以使用以下命令創建 RAID 設備<code>md0</code> （即 /dev/md0），並在所有新創建的分區中應用 RAID 級別，然後確認 RAID 設置。</p><pre><code># mdadm --create /dev/md0 --level=6 --raid-devices=4 /dev/sdb1 /dev/sdc1 /dev/sdd1 /dev/sde1
# cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-Raid-6-Device.png" alt="Create Raid 6 Device"></p><p><em>創建 Raid 6 設備</em></p><p>7、 你還可以使用 watch 命令來查看當前創建 RAID 的進程，如下圖所示。</p><pre><code># watch -n1 cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-6-Process.png" alt="Check Raid 6 Process"></p><p><em>檢查 RAID 6 創建過程</em></p><p>8、 使用以下命令驗證 RAID 設備。</p><pre><code># mdadm -E /dev/sd[b-e]1
</code></pre><p><strong>注意</strong>::上述命令將顯示四個磁盤的信息，這是相當長的，所以沒有截取其完整的輸出。</p><p>9、 接下來，驗證 RAID 陣列，以確認重新同步過程已經開始。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-6-Array.png" alt="Check Raid 6 Array"></p><p><em>檢查 Raid 6 陣列</em></p><h3 id="第4步-在-raid-設備上創建文件系統" tabindex="-1">第4步：在 RAID 設備上創建文件系統 <a class="header-anchor" href="#第4步-在-raid-設備上創建文件系統" aria-label="Permalink to “第4步：在 RAID 設備上創建文件系統”">​</a></h3><p>10、 使用 ext4 為<code>/dev/md0</code>創建一個文件系統，並將它掛載在 /mnt/raid6 。這裏我們使用的是 ext4，但你可以根據你的選擇使用任意類型的文件系統。</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-File-System-on-Raid.png" alt="Create File System on Raid"></p><p><em>在 RAID 6 上創建文件系統</em></p><p>11、 將創建的文件系統掛載到 /mnt/raid6，並驗證掛載點下的文件，我們可以看到 lost+found 目錄。</p><pre><code># mkdir /mnt/raid6
# mount /dev/md0 /mnt/raid6/
# ls -l /mnt/raid6/
</code></pre><p>12、 在掛載點下創建一些文件，在任意文件中添加一些文字並驗證其內容。</p><pre><code># touch /mnt/raid6/raid6_test.txt
# ls -l /mnt/raid6/
# echo &quot;tecmint raid setups&quot; &gt; /mnt/raid6/raid6_test.txt
# cat /mnt/raid6/raid6_test.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Raid-Content.png" alt="Verify Raid Content"></p><p><em>驗證 RAID 內容</em></p><p>13、 在 /etc/fstab 中添加以下條目使系統啓動時自動掛載設備，操作系統環境不同掛載點可能會有所不同。</p><pre><code># vim /etc/fstab

/dev/md0                /mnt/raid6              ext4    defaults        0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Automount-Raid-Device.png" alt="Automount Raid 6 Device"></p><p><em>自動掛載 RAID 6 設備</em></p><p>14、 接下來，執行<code>mount -a</code>命令來驗證 fstab 中的條目是否有錯誤。</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Automount-Raid-Devices.png" alt="Verify Raid Automount"></p><p><em>驗證 RAID 是否自動掛載</em></p><h3 id="第5步-保存-raid-6-的配置" tabindex="-1">第5步：保存 RAID 6 的配置 <a class="header-anchor" href="#第5步-保存-raid-6-的配置" aria-label="Permalink to “第5步：保存 RAID 6 的配置”">​</a></h3><p>15、 請注意，默認情況下 RAID 沒有配置文件。我們需要使用以下命令手動保存它，然後檢查設備<code>/dev/md0</code>的狀態。</p><pre><code># mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf
# cat /etc/mdadm.conf
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-Status.png" alt="Save Raid 6 Configuration"></p><p><em>保存 RAID 6 配置</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-Status.png" alt="Check Raid 6 Status"></p><p><em>檢查 RAID 6 狀態</em></p><h3 id="第6步-添加備用磁盤" tabindex="-1">第6步：添加備用磁盤 <a class="header-anchor" href="#第6步-添加備用磁盤" aria-label="Permalink to “第6步：添加備用磁盤”">​</a></h3><p>16、 現在，已經使用了4個磁盤，並且其中兩個作為奇偶校驗信息來使用。在某些情況下，如果任意一個磁盤出現故障，我們仍可以得到數據，因為在 RAID 6 使用雙奇偶校驗。</p><p>如果第二個磁盤也出現故障，在第三塊磁盤損壞前我們可以添加一個​​新的。可以在創建 RAID 集時加入一個備用磁盤，但我在創建 RAID 集合前沒有定義備用的磁盤。不過，我們可以在磁盤損壞後或者創建 RAID 集合時添加一塊備用磁盤。現在，我們已經創建好了 RAID，下面讓我演示如何添加備用磁盤。</p><p>為了達到演示的目的，我已經熱插入了一個新的 HDD 磁盤（即 /dev/sdf），讓我們來驗證接入的磁盤。</p><pre><code># ls -l /dev/ | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-New-Disk.png" alt="Check New Disk"></p><p><em>檢查新磁盤</em></p><p>17、 現在再次確認新連接的磁盤沒有配置過 RAID ，使用 mdadm 來檢查。</p><pre><code># mdadm --examine /dev/sdf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-on-New-Disk.png" alt="Check Raid on New Disk"></p><p><em>在新磁盤中檢查 RAID</em></p><p><strong>注意</strong>: 像往常一樣，我們早前已經為四個磁盤創建了分區，同樣，我們使用 fdisk 命令為新插入的磁盤創建新分區。</p><pre><code># fdisk /dev/sdf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-Partition-on-sdf.png" alt="Create sdf Partition"></p><p><em>為 /dev/sdf 創建分區</em></p><p>18、 在 /dev/sdf 創建新的分區後，在新分區上確認沒有 RAID，然後將備用磁盤添加到 RAID 設備 /dev/md0 中，並驗證添加的設備。</p><pre><code># mdadm --examine /dev/sdf
# mdadm --examine /dev/sdf1
# mdadm --add /dev/md0 /dev/sdf1
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Raid-on-sdf.png" alt="Verify Raid on sdf Partition"></p><p><em>在 sdf 分區上驗證 Raid</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Add-sdf-Partition-to-Raid.png" alt="Add sdf Partition to Raid"></p><p>*添加 sdf 分區到 RAID *</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-sdf-Details.png" alt="Verify sdf Partition Details"></p><p><em>驗證 sdf 分區信息</em></p><h3 id="第7步-檢查-raid-6-容錯" tabindex="-1">第7步：檢查 RAID 6 容錯 <a class="header-anchor" href="#第7步-檢查-raid-6-容錯" aria-label="Permalink to “第7步：檢查 RAID 6 容錯”">​</a></h3><p>19、 現在，讓我們檢查備用驅動器是否能自動工作，當我們陣列中的任何一個磁盤出現故障時。為了測試，我將一個磁盤手工標記為故障設備。</p><p>在這裏，我們標記 /dev/sdd1 為故障磁盤。</p><pre><code># mdadm --manage --fail /dev/md0 /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-6-Failover.png" alt="Check Raid 6 Fault Tolerance"></p><p><em>檢查 RAID 6 容錯</em></p><p>20、 讓我們查看 RAID 的詳細信息，並檢查備用磁盤是否開始同步。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Auto-Raid-Syncing.png" alt="Check Auto Raid Syncing"></p><p><em>檢查 RAID 自動同步</em></p><p><strong>哇塞!</strong> 這裏，我們看到備用磁盤激活了，並開始重建進程。在底部，我們可以看到有故障的磁盤 /dev/sdd1 標記為 faulty。可以使用下面的命令查看進程重建。</p><pre><code># cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Raid-6-Auto-Syncing.png" alt="Raid 6 Auto Syncing"></p><p><em>RAID 6 自動同步</em></p><h3 id="結論" tabindex="-1">結論: <a class="header-anchor" href="#結論" aria-label="Permalink to “結論:”">​</a></h3><p>在這裏，我們看到了如何使用四個磁盤設置 RAID 6。這種 RAID 級別是具有高冗餘的昂貴設置之一。在接下來的文章中，我們將看到如何建立一個嵌套的 RAID 10 甚至更多。請繼續關注。</p><hr>`,121)),a("p",null,[e[5]||(e[5]=t("via: ",-1)),i(d,{href:"http://www.tecmint.com/create-raid-6-in-linux/"},{default:p(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/create-raid-6-in-linux/",-1)])]),_:1})]),a("p",null,[e[9]||(e[9]=t("作者：",-1)),i(d,{href:"http://www.tecmint.com/author/babinlonston/"},{default:p(()=>[...e[6]||(e[6]=[t("Babin Lonston",-1)])]),_:1}),e[10]||(e[10]=t(" 譯者：",-1)),i(d,{href:"https://github.com/strugglingyouth"},{default:p(()=>[...e[7]||(e[7]=[t("strugglingyouth",-1)])]),_:1}),e[11]||(e[11]=t(" 校對：",-1)),i(d,{href:"https://github.com/wxy"},{default:p(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[14]||(e[14]=t("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原創翻譯，",-1)),i(d,{href:"https://linux.cn/"},{default:p(()=>[...e[13]||(e[13]=[t("Linux中國",-1)])]),_:1}),e[16]||(e[16]=t(" 榮譽推出",-1))])])}const f=o(c,[["render",l]]);export{g as __pageData,f as default};
